//! Automatic update engine (ADR-008, 2026-10-28).
//!
//! One installer exists (the family build, ADR-006 distribution addendum)
//! and the landing page serves it. This module turns that fact into an
//! in-app update flow with NO new dependencies and no new trust surface:
//!
//! * **Check**: fetch `https://remote.deepflux.space/latest.json` (HTTPS,
//!   same origin as the manual download) at startup + every 24 h, or on
//!   demand (Help → Check for updates). The manifest is generated by
//!   `scripts/publish-landing.sh` together with the landing page, so it
//!   cannot silently drift from the shipped installer (the
//!   stale-website trap that bit 0.5.x).
//! * **Download**: the user presses Update (installing closes the app —
//!   it is never forced, and never during a live session). The download
//!   reuses the hardened segmented engine (`dl.rs`) into an
//!   `updates/` staging dir under app data, then verifies the installer
//!   byte-for-byte against the manifest's SHA-256 before offering to run
//!   it. An interrupted download resumes via the same `.dfresume`
//!   machinery as agent downloads.
//! * **Install**: run the NSIS installer silently (`/S`; per-user install
//!   mode = no UAC), quit, and relaunch the app once the installer
//!   exits. The relaunch is a detached `cmd` wrapper because the
//!   installer replaces the running exe — the app must be gone first.
//!
//! Trust model (ADR-008): identical to the manual download — HTTPS to
//! remote.deepflux.space, plus a SHA-256 pinned in the same manifest
//! (protects against transport/CDN corruption and truncated files, not
//! against a compromised origin). Code signing + signature verification
//! is the documented upgrade path once a certificate exists.
//!
//! Invariant 3: no queues here at all — one poller thread with a 1 s
//! tick, one download thread at a time (the state machine refuses
//! overlaps), bounded 64 KiB manifest body.

use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::{Duration, Instant};

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tauri::{AppHandle, Emitter, Manager};

#[cfg(windows)]
use std::os::windows::process::CommandExt;

/// Where the published manifest lives. Override for dev/tests with the
/// `DEEPFLUX_UPDATE_MANIFEST` env var (e.g. a loopback server).
pub const DEFAULT_MANIFEST_URL: &str = "https://remote.deepflux.space/latest.json";
/// `product` field of the manifest — a mismatched product is not ours.
const PRODUCT_ID: &str = "remote-desktop";
/// Startups do not check before this delay (let the engine settle first).
const FIRST_CHECK_DELAY: Duration = Duration::from_secs(20);
/// Steady-state re-check cadence.
const CHECK_INTERVAL: Duration = Duration::from_secs(24 * 60 * 60);
/// Manifest body cap — a real manifest is well under 2 KiB.
const MANIFEST_MAX_BYTES: u64 = 64 * 1024;
/// Installer-size ceiling (defense-in-depth on top of the global dl cap:
/// the installer is ~8 MB; a manifest claiming hundreds of MB is wrong).
const MAX_INSTALLER_BYTES: u64 = 256 * 1024 * 1024;
/// Progress-poll cadence while the installer downloads.
const PROGRESS_POLL: Duration = Duration::from_millis(400);
/// Event channel (updater → UI); payload = [`UpdateUiState`], metadata only.
pub const EVENT: &str = "update://state";
/// Slack after the installer exits before the wrapper relaunches the app.
const INSTALLER_SETTLE_PINGS: u32 = 4;

// ---------------------------------------------------------------------------
// Manifest
// ---------------------------------------------------------------------------

/// The published `latest.json` (generated by `scripts/publish-landing.sh`).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UpdateManifest {
    /// Must equal [`PRODUCT_ID`] — guards against pointing this client at
    /// some other product's manifest.
    pub product: String,
    /// Dotted-numeric version; strictly greater than the running one to
    /// be offered.
    pub version: String,
    /// HTTPS URL of the installer. Must sit on the SAME host that served
    /// the manifest (origin pin).
    pub url: String,
    /// SHA-256 of the installer bytes, 64 hex chars.
    pub sha256_hex: String,
    /// Exact installer size in bytes (pre-check before hashing).
    pub size_bytes: u64,
    /// One-line human notes for the update banner ("what's new").
    #[serde(default)]
    pub notes: String,
    /// ISO date (display only).
    #[serde(default)]
    pub published_at: String,
}

/// Dotted-numeric version compare ("0.9.0" vs "0.8.1").
fn parse_version(v: &str) -> Option<Vec<u64>> {
    v.trim()
        .split('.')
        .map(|part| part.trim().parse::<u64>().ok())
        .collect()
}

/// True when `latest` is strictly newer than `current`. Unparseable
/// versions never win — a malformed manifest is ignored, never offered.
pub fn is_newer(latest: &str, current: &str) -> bool {
    match (parse_version(latest), parse_version(current)) {
        (Some(l), Some(c)) => l > c,
        _ => false,
    }
}

/// Fetch + validate the manifest. Validation failures are hard errors —
/// an updater that "tries anyway" on a malformed manifest is a downgrade
/// attack surface, not resilience.
fn fetch_manifest(url: &str) -> Result<UpdateManifest, String> {
    let (url, _) = crate::dl::validate_url(url, true)?;
    let agent = node_runtime::http::https_agent(Duration::from_secs(15), "remote-desktop-updater");
    let resp = agent
        .get(&url)
        .call()
        .map_err(|e| format!("update check failed: {e}"))?;
    if resp.status() != 200 {
        return Err(format!("update check failed: HTTP {}", resp.status()));
    }
    use std::io::Read;
    let mut body = String::new();
    resp.into_reader()
        .take(MANIFEST_MAX_BYTES + 1)
        .read_to_string(&mut body)
        .map_err(|e| format!("update check failed while reading: {e}"))?;
    if body.len() as u64 > MANIFEST_MAX_BYTES {
        return Err("update manifest is larger than expected — refusing".into());
    }
    let manifest: UpdateManifest =
        serde_json::from_str(&body).map_err(|e| format!("bad manifest: {e}"))?;
    validate_manifest(&manifest, &url)?;
    Ok(manifest)
}

/// Structural validation independent of transport (unit-testable).
fn validate_manifest(m: &UpdateManifest, manifest_url: &str) -> Result<(), String> {
    if m.product != PRODUCT_ID {
        return Err(format!("manifest is for product {:?}, not us", m.product));
    }
    if parse_version(&m.version).is_none() {
        return Err(format!(
            "manifest version {:?} is not dotted numeric",
            m.version
        ));
    }
    let (_, host) = crate::dl::validate_url(&m.url, true)
        .map_err(|e| format!("manifest installer URL rejected: {e}"))?;
    // Origin pin: the installer must come from the same host that served
    // the manifest (both are remote.deepflux.space in production).
    let manifest_host = manifest_url
        .split_once("://")
        .and_then(|(_, rest)| rest.split(['/', '?', '#']).next())
        .and_then(|authority| authority.rsplit('@').next())
        .and_then(|authority| authority.split(':').next())
        .unwrap_or("")
        .to_ascii_lowercase();
    if host != manifest_host {
        return Err(format!(
            "manifest installer host {host:?} is not the manifest's own host {manifest_host:?}"
        ));
    }
    let sha = m.sha256_hex.trim().to_ascii_lowercase();
    if sha.len() != 64 || !sha.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err("manifest sha256_hex is not 64 hex chars".into());
    }
    if m.size_bytes == 0 || m.size_bytes > MAX_INSTALLER_BYTES {
        return Err(format!(
            "manifest size_bytes {} is out of range",
            m.size_bytes
        ));
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// State (managed in AppServices, emitted to the webview on every change)
// ---------------------------------------------------------------------------

/// Updater state for the UI. Field names deliberately avoid the IPC
/// surface's forbidden substrings (no `bytes`): progress is a percent and
/// a human size string, both clean by the ipc_surface walk.
#[derive(Debug, Clone, Default, Serialize)]
pub struct UpdateUiState {
    /// idle | checking | available | none | downloading | ready | installing
    /// | error
    pub status: String,
    /// Which step an error belongs to: check | download | install (empty
    /// outside errors) — the UI words the failure by stage.
    pub stage: String,
    pub current_version: String,
    pub latest_version: String,
    pub notes: String,
    /// Human size of the installer ("7.3 MB") once a manifest is known.
    pub size_text: String,
    /// 0–100 while downloading.
    pub progress_percent: u8,
    pub error: String,
}

/// Managed state + the poller's control flags.
pub struct UpdateEngine {
    state: Mutex<UpdateUiState>,
    /// The staged, verified installer path (valid in status "ready").
    staged: Mutex<Option<PathBuf>>,
    /// Version the user dismissed this run ("Later") — the daily check
    /// does not re-notify for it.
    dismissed: Mutex<Option<String>>,
    /// Set by `update_check` to force the poller to check immediately.
    force_check: AtomicBool,
    /// A download is in flight (one at a time).
    download_running: AtomicBool,
}

impl Default for UpdateEngine {
    fn default() -> Self {
        Self {
            state: Mutex::new(UpdateUiState {
                status: "idle".into(),
                current_version: env!("CARGO_PKG_VERSION").into(),
                ..UpdateUiState::default()
            }),
            staged: Mutex::new(None),
            dismissed: Mutex::new(None),
            force_check: AtomicBool::new(false),
            download_running: AtomicBool::new(false),
        }
    }
}

impl UpdateEngine {
    pub fn state(&self) -> UpdateUiState {
        self.state.lock().map(|s| s.clone()).unwrap_or_default()
    }

    /// Help → Check for updates: the poller picks this up within a tick,
    /// and the UI shows "checking" right away (an explicit press must
    /// have a visible answer).
    pub fn force_check_now(&self, app: &AppHandle) {
        self.force_check.store(true, Ordering::Relaxed);
        self.mutate(app, |s| {
            if !matches!(s.status.as_str(), "downloading" | "ready" | "installing") {
                s.status = "checking".into();
                s.stage = "check".into();
                s.error.clear();
            }
        });
    }

    /// "Not now": quiet for the offered version until the app restarts.
    /// Clearing an ERROR never declines the update — it just closes the
    /// banner (the version comes back with the next check or Try again).
    pub fn dismiss(&self, app: &AppHandle) {
        let (status, latest) = {
            let state = self.state();
            (state.status.clone(), state.latest_version.clone())
        };
        if matches!(status.as_str(), "available" | "ready") {
            *self.dismissed.lock().unwrap_or_else(|e| e.into_inner()) = Some(latest);
        }
        self.mutate(app, |s| {
            s.status = "idle".into();
            s.error.clear();
        });
    }

    fn mutate(&self, app: &AppHandle, f: impl FnOnce(&mut UpdateUiState)) {
        {
            let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
            f(&mut state);
        }
        let _ = app.emit(EVENT, self.state());
    }

    /// Surface a failure as the error state (an explicit press must never
    /// fail silently). `stage` words the banner title; the detail goes to
    /// stderr for field debugging — the user-facing string stays plain.
    fn fail(&self, app: &AppHandle, stage: &str, user_copy: &str, detail: &str) {
        eprintln!("[update] {stage} failure: {detail}");
        self.mutate(app, |s| {
            s.status = "error".into();
            s.stage = stage.into();
            s.error = user_copy.to_owned();
        });
    }
}

/// The manifest URL (env override for dev/tests).
fn manifest_url() -> String {
    std::env::var("DEEPFLUX_UPDATE_MANIFEST").unwrap_or_else(|_| DEFAULT_MANIFEST_URL.into())
}

/// Where staged installers live (`<app data>/updates`).
fn staging_dir(app: &AppHandle) -> Result<PathBuf, String> {
    app.path()
        .app_data_dir()
        .map(|dir| dir.join("updates"))
        .map_err(|e| format!("no app data dir: {e}"))
}

fn human_size(bytes: u64) -> String {
    let mb = bytes as f64 / (1024.0 * 1024.0);
    if mb >= 1.0 {
        format!("{mb:.1} MB")
    } else {
        format!("{} kB", bytes / 1024)
    }
}

// ---------------------------------------------------------------------------
// Poller (startup + daily + on-demand)
// ---------------------------------------------------------------------------

/// Background poller: waits out [`FIRST_CHECK_DELAY`], checks, then
/// re-checks every [`CHECK_INTERVAL`] (or immediately when forced). The
/// settings toggle (`auto_update`) gates the automatic checks only — an
/// explicit Help → Check for updates always runs.
pub fn spawn_poller(app: AppHandle) {
    std::thread::Builder::new()
        .name("update-poller".into())
        .spawn(move || {
            let mut next_check = Instant::now() + FIRST_CHECK_DELAY;
            loop {
                std::thread::sleep(Duration::from_secs(1));
                let forced = {
                    let services = app.state::<crate::commands::AppServices>();
                    services.update.force_check.swap(false, Ordering::Relaxed)
                };
                if !forced && Instant::now() < next_check {
                    continue;
                }
                next_check = Instant::now() + CHECK_INTERVAL;
                let auto = {
                    let services = app.state::<crate::commands::AppServices>();
                    services
                        .store
                        .lock()
                        .map(|s| s.settings().auto_update)
                        .unwrap_or(true)
                };
                if forced || auto {
                    run_check(&app, forced);
                }
            }
        })
        .expect("spawn update poller");
}

/// One check cycle: fetch, compare, update state. A failed check only
/// surfaces as an error when the user asked (`forced`) — and never erases
/// a standing "available" offer (a flaky daily re-check must not silently
/// retract an update the user already saw). Background failures stay
/// quiet so an offline machine never sees update noise at startup.
fn run_check(app: &AppHandle, forced: bool) {
    let services = app.state::<crate::commands::AppServices>();
    // Never clobber an in-flight update with a re-check: the staged
    // "ready" installer and a running download outrank fresh manifest
    // data (the next cycle re-offers if the version moved again).
    let status = services.update.state().status;
    if matches!(status.as_str(), "downloading" | "ready" | "installing") {
        return;
    }
    let manifest = match fetch_manifest(&manifest_url()) {
        Ok(m) => m,
        Err(err) => {
            let services = app.state::<crate::commands::AppServices>();
            if status == "available" {
                // Keep the offer; log the transient failure only.
                eprintln!("[update] re-check failed under a standing offer: {err}");
                return;
            }
            if forced {
                services.update.fail(
                    app,
                    "check",
                    "couldn't reach the update service just now — nothing was changed; \
                     try again in a little while",
                    &err,
                );
            } else {
                services.update.mutate(app, |s| {
                    s.status = "idle".into();
                    s.error.clear();
                });
                eprintln!("[update] background check failed: {err}");
            }
            return;
        }
    };
    let services = app.state::<crate::commands::AppServices>();
    let engine = &services.update;
    let current = engine.state().current_version;
    // A forced (Help menu) check ignores a previous "Not now" — the
    // settings-copy promise "Help menu works either way" includes this.
    let dismissed = if forced {
        None
    } else {
        engine
            .dismissed
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .clone()
    };
    let is_new = is_newer(&manifest.version, &current);
    let suppressed = dismissed.as_deref() == Some(manifest.version.as_str());
    let version = manifest.version.clone();
    let notes = manifest.notes.clone();
    let size_text = human_size(manifest.size_bytes);
    *services
        .update_manifest
        .lock()
        .unwrap_or_else(|e| e.into_inner()) = Some(manifest);
    engine.mutate(app, |s| {
        s.latest_version = version;
        s.notes = notes;
        s.size_text = size_text;
        s.error.clear();
        s.status = if is_new && !suppressed {
            "available".into()
        } else if forced {
            // The explicit press gets its answer, even when it's "no".
            "none".into()
        } else {
            // Up to date (or dismissed for this run): quiet state.
            "idle".into()
        };
    });
}

// ---------------------------------------------------------------------------
// Download + verify
// ---------------------------------------------------------------------------

/// Remove staged files from OTHER versions, plus a same-version target
/// with no resume state (a previously staged-but-unverified leftover
/// always re-downloads). An interrupted target and its `.dfresume` map
/// stay — the dl engine resumes them.
fn purge_stale(dir: &Path, keep: &str) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let Some(name) = entry.file_name().to_str().map(str::to_owned) else {
            continue;
        };
        if !name.starts_with("update-") {
            continue;
        }
        if name == format!("{keep}.dfresume") || name == format!("{keep}.dfresume.tmp") {
            continue;
        }
        if name == keep && dir.join(format!("{keep}.dfresume")).exists() {
            continue; // interrupted target: the dl engine resumes it
        }
        let _ = std::fs::remove_file(entry.path());
    }
}

/// Start the installer download (user pressed Update). Runs on its own
/// thread through the shared `dl` engine into the staging dir. Every
/// early failure resets the single-download flag AND lands in the error
/// state — an explicit press must never fail silently.
pub fn start_download(app: AppHandle) -> Result<(), String> {
    let services = app.state::<crate::commands::AppServices>();
    let engine = &services.update;
    if engine.download_running.swap(true, Ordering::Relaxed) {
        return Err("an update download is already running".into());
    }
    let bail = |message: &str, detail: &str| -> String {
        engine.download_running.store(false, Ordering::Relaxed);
        engine.fail(&app, "download", message, detail);
        message.to_owned()
    };
    let manifest = services
        .update_manifest
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .clone();
    let Some(manifest) = manifest else {
        return Err(bail(
            "no update is known yet — use Check for updates first",
            "no manifest held",
        ));
    };
    let dir = match staging_dir(&app) {
        Ok(dir) => dir,
        Err(err) => return Err(bail("couldn't prepare the update folder — try again", &err)),
    };
    // A handle clone for the worker so spawn failure can still answer.
    let thread_app = app.clone();
    let spawn = std::thread::Builder::new()
        .name("update-download".into())
        .spawn(move || run_download(thread_app, manifest, dir));
    if let Err(e) = spawn {
        return Err(bail(
            "couldn't start the download — try again in a little while",
            &format!("spawn failed: {e}"),
        ));
    }
    Ok(())
}

fn run_download(app: AppHandle, manifest: UpdateManifest, dir: PathBuf) {
    let services = app.state::<crate::commands::AppServices>();
    let engine = &services.update;
    let finish = |status: &str, error: &str| {
        engine.download_running.store(false, Ordering::Relaxed);
        engine.mutate(&app, |s| {
            s.status = status.to_owned();
            if status == "error" {
                s.stage = "download".into();
                s.error = error.to_owned();
            } else {
                s.error.clear();
            }
        });
    };
    let fail = |user_copy: &str, detail: &str| {
        eprintln!("[update] download failure: {detail}");
        finish("error", user_copy);
    };
    let filename = crate::dl::safe_filename(&format!("update-{}-setup.exe", manifest.version));
    purge_stale(&dir, &filename);
    engine.mutate(&app, |s| {
        s.status = "downloading".into();
        s.stage = "download".into();
        s.progress_percent = 0;
        s.error.clear();
    });
    let job = match crate::dl::start_in_dir(&manifest.url, Some(&filename), true, Some(&dir)) {
        Ok(job) => job,
        Err(err) => {
            return fail(
                "couldn't start the download — try again in a little while",
                &err,
            );
        }
    };
    // The dl engine suffix-renames an occupied target ("2-…"); verify the
    // file where it actually landed (purge_stale normally prevents this).
    let staged_path = PathBuf::from(&job.path);
    if staged_path.file_name().and_then(|n| n.to_str()) != Some(filename.as_str()) {
        return fail(
            "the update folder has a locked leftover file — close other apps and try again",
            &format!("dl renamed the target to {}", job.path),
        );
    }
    loop {
        let Some(info) = crate::dl::wait(&job.id, PROGRESS_POLL) else {
            return fail(
                "the download stopped unexpectedly — try again",
                "job vanished",
            );
        };
        let total = manifest.size_bytes.max(info.total_bytes);
        let percent = if total > 0 {
            ((info.downloaded_bytes as f64 / total as f64) * 100.0) as u8
        } else {
            0
        };
        engine.mutate(&app, |s| s.progress_percent = percent.min(100));
        if info.status == "done" {
            break;
        }
        if info.status == "error" {
            return fail(
                "the download didn't complete — trying again picks up where it left off",
                &info.error,
            );
        }
    }
    // Verify: exact size, then SHA-256 against the manifest. Any mismatch
    // deletes the staged file — an unverified installer never runs.
    if let Err(user_copy) = verify_staged(&staged_path, &manifest) {
        let _ = std::fs::remove_file(&staged_path);
        return fail(
            &user_copy,
            &format!("verify failed for {}", staged_path.display()),
        );
    }
    *engine.staged.lock().unwrap_or_else(|e| e.into_inner()) = Some(staged_path);
    finish("ready", "");
}

/// Size + SHA-256 verification of a downloaded installer against its
/// manifest. Pure (filesystem only) so the trust gate is unit-testable;
/// returns plain-language copy for the user, detail via the caller's log.
fn verify_staged(path: &Path, manifest: &UpdateManifest) -> Result<(), String> {
    match std::fs::metadata(path) {
        Ok(meta) if meta.len() == manifest.size_bytes => {}
        Ok(_) => {
            return Err(
                "the downloaded update was incomplete, so it was deleted — please try again".into(),
            );
        }
        Err(e) => {
            return Err(format!(
                "the downloaded update disappeared before checking: {e}"
            ));
        }
    }
    match sha256_file(path) {
        Ok(actual) if actual == manifest.sha256_hex.trim().to_ascii_lowercase() => Ok(()),
        Ok(_) => Err(
            "the downloaded update didn't match the official copy, so it was deleted to be safe — please try again".into(),
        ),
        Err(e) => Err(format!("couldn't check the downloaded update: {e}")),
    }
}

fn sha256_file(path: &Path) -> Result<String, String> {
    use std::io::Read;
    let mut file = std::fs::File::open(path).map_err(|e| e.to_string())?;
    let mut hasher = Sha256::new();
    let mut buf = [0u8; 64 * 1024];
    loop {
        let n = file.read(&mut buf).map_err(|e| e.to_string())?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    Ok(hex_lower(&hasher.finalize()))
}

fn hex_lower(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

// ---------------------------------------------------------------------------
// Install (silent NSIS + relaunch)
// ---------------------------------------------------------------------------

/// cmd metacharacters that would break the wrapper script — paths
/// containing them skip the relaunch wrapper (rare; the installer still
/// runs, the user starts the app themselves afterwards).
fn path_safe_for_cmd(path: &str) -> bool {
    !path.contains(['&', '^', '%', '<', '>', '|'])
}

/// The detached wrapper: wait for the app to exit, run the installer
/// silently to completion, settle, then start the app again. One
/// `cmd /d /c` script.
///
/// Three shapes by path safety (a path with a cmd metacharacter must not
/// go into a script — see [`path_safe_for_cmd`]):
/// * both paths safe → install + relaunch;
/// * only the app exe unsafe → install with grace, no relaunch;
/// * installer itself unsafe → caller falls back to a bare spawn.
#[derive(Debug)]
enum InstallCommand {
    /// Full script: grace, silent install, settle, relaunch the app.
    InstallAndRelaunch(String),
    /// Script: grace + silent install only (user starts the app after).
    InstallOnly(String),
    /// Run the installer directly, no wrapper (extreme-path residual).
    Bare,
}

fn build_install_command(installer: &Path, app_exe: &Path) -> InstallCommand {
    let Some(installer_s) = installer.to_str() else {
        return InstallCommand::Bare;
    };
    if !path_safe_for_cmd(installer_s) {
        return InstallCommand::Bare;
    }
    match app_exe.to_str().filter(|exe| path_safe_for_cmd(exe)) {
        Some(app_exe) => InstallCommand::InstallAndRelaunch(format!(
            "ping -n 3 127.0.0.1 >nul \
             & start /wait \"\" \"{installer_s}\" /S \
             & ping -n {INSTALLER_SETTLE_PINGS} 127.0.0.1 >nul \
             & start \"\" \"{app_exe}\""
        )),
        None => InstallCommand::InstallOnly(format!(
            // Same grace as the full wrapper: the tauri silent installer
            // force-kills a still-running app (RmShutdown), which would
            // skip the clean engine shutdown — give teardown the lead.
            "ping -n 3 127.0.0.1 >nul & start /wait \"\" \"{installer_s}\" /S"
        )),
    }
}

/// A role state that means "no session machinery in flight" — anything
/// else (ConsentPrompted, Exchanging, Connecting, Connected on the host;
/// Requesting, Offering, Connecting, Connected on the controller) means
/// killing the app would die under a live session attempt.
const QUIET_STATES: [&str; 4] = ["Idle", "Registering", "Online", "Disconnected"];

/// Run the staged installer. Refuses while any session machinery is live
/// (installing kills the app — never under an active or in-flight
/// session) and when nothing verified is staged; re-verifies the staged
/// installer at install time (it may have sat on disk for days).
pub fn install(app: AppHandle) -> Result<(), String> {
    let services = app.state::<crate::commands::AppServices>();
    let engine = &services.update;
    let bail = |message: &str| -> String {
        engine.fail(&app, "install", message, message);
        message.to_owned()
    };
    if engine.state().status != "ready" {
        return Err("no verified update is ready to install".into());
    }
    let (host_state, controller_state) = services
        .engine
        .lock()
        .map(|slot| {
            slot.as_ref()
                .map(|handle| {
                    let s = handle.status();
                    (s.host_state, s.controller_state)
                })
                .unwrap_or_else(|| ("Idle".into(), "Idle".into()))
        })
        .unwrap_or_else(|_| ("Idle".into(), "Idle".into()));
    if !QUIET_STATES.contains(&host_state.as_str())
        || !QUIET_STATES.contains(&controller_state.as_str())
    {
        return Err(bail(
            "finish the remote session first — updating restarts DeepFlux",
        ));
    }
    let manifest = services
        .update_manifest
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .clone();
    let staged = engine
        .staged
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .clone();
    let Some(staged) = staged else {
        return Err(bail("no verified update is ready to install"));
    };
    if let Some(manifest) = manifest.as_ref()
        && let Err(err) = verify_staged(&staged, manifest)
    {
        let _ = std::fs::remove_file(&staged);
        return Err(bail(&format!(
            "the saved update no longer passes its check — {err}. Please download it again."
        )));
    }
    engine.mutate(&app, |s| {
        s.status = "installing".into();
        s.stage = "install".into();
        s.error.clear();
    });
    let app_exe = match std::env::current_exe() {
        Ok(exe) => exe,
        Err(e) => return Err(bail(&format!("couldn't locate the app program: {e}"))),
    };
    let spawned = match build_install_command(&staged, &app_exe) {
        InstallCommand::InstallAndRelaunch(script) | InstallCommand::InstallOnly(script) => {
            std::process::Command::new("cmd.exe")
                .args(["/d", "/c", &script])
                .creation_flags(detached_flags())
                .spawn()
        }
        InstallCommand::Bare => std::process::Command::new(&staged)
            .arg("/S")
            .creation_flags(detached_flags())
            .spawn(),
    };
    if let Err(e) = spawned {
        return Err(bail(&format!("couldn't start the installer: {e}")));
    }
    // The wrapper now owns the machine: shut down and get out of the way.
    crate::commands::shutdown_and_exit(&app);
    Ok(())
}

#[cfg(windows)]
fn detached_flags() -> u32 {
    // CREATE_NO_WINDOW | DETACHED_PROCESS
    0x0800_0008
}

#[cfg(not(windows))]
fn detached_flags() -> u32 {
    0
}

