#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn version_comparison_table() {
        assert!(is_newer("0.9.0", "0.8.1"));
        assert!(is_newer("0.8.2", "0.8.1"));
        assert!(is_newer("1.0.0", "0.9.9"));
        assert!(is_newer("0.10.0", "0.9.0")); // numeric, not lexicographic
        assert!(is_newer("0.9.0.1", "0.9.0"));
        assert!(!is_newer("0.8.1", "0.8.1"));
        assert!(!is_newer("0.8.0", "0.8.1"));
        // Malformed never wins.
        assert!(!is_newer("latest", "0.8.1"));
        assert!(!is_newer("", "0.8.1"));
        assert!(!is_newer("0.9", "not-a-version"));
    }

    fn manifest_fixture() -> UpdateManifest {
        UpdateManifest {
            product: PRODUCT_ID.into(),
            version: "9.9.9".into(),
            url: "https://remote.deepflux.space/download/Remote-Desktop-9.9.9-x64-setup.exe".into(),
            sha256_hex: "a".repeat(64),
            size_bytes: 7_300_000,
            notes: "test".into(),
            published_at: "2026-10-28".into(),
        }
    }

    const MANIFEST_URL: &str = "https://remote.deepflux.space/latest.json";

    #[test]
    fn manifest_validation_table() {
        assert!(validate_manifest(&manifest_fixture(), MANIFEST_URL).is_ok());
        let mut m = manifest_fixture();
        m.product = "other-product".into();
        assert!(validate_manifest(&m, MANIFEST_URL).is_err());
        // Installer on a different host than the manifest (origin pin).
        let mut m = manifest_fixture();
        m.url = "https://evil.example.com/x.exe".into();
        assert!(validate_manifest(&m, MANIFEST_URL).is_err());
        // http installer.
        let mut m = manifest_fixture();
        m.url = "http://remote.deepflux.space/x.exe".into();
        assert!(validate_manifest(&m, MANIFEST_URL).is_err());
        // Bad hashes.
        for bad in ["", "abc", &"g".repeat(64), &"a".repeat(63)] {
            let mut m = manifest_fixture();
            m.sha256_hex = bad.into();
            assert!(validate_manifest(&m, MANIFEST_URL).is_err(), "sha {bad:?}");
        }
        // Size bounds.
        for bad in [0u64, MAX_INSTALLER_BYTES + 1, crate::dl::MAX_BYTES + 1] {
            let mut m = manifest_fixture();
            m.size_bytes = bad;
            assert!(validate_manifest(&m, MANIFEST_URL).is_err(), "size {bad}");
        }
        // Non-dotted version.
        let mut m = manifest_fixture();
        m.version = "nine".into();
        assert!(validate_manifest(&m, MANIFEST_URL).is_err());
        // Subdomain is NOT the same host (no suffix matching — the pin is
        // exact).
        let mut m = manifest_fixture();
        m.url = "https://cdn.remote.deepflux.space/x.exe".into();
        assert!(validate_manifest(&m, MANIFEST_URL).is_err());
    }

    #[test]
    fn manifest_json_round_trip() {
        let json = serde_json::to_string(&manifest_fixture()).unwrap();
        let back: UpdateManifest = serde_json::from_str(&json).unwrap();
        assert_eq!(back.version, "9.9.9");
        // notes/published_at are optional on the wire.
        let minimal = serde_json::json!({
            "product": PRODUCT_ID,
            "version": "1.0.0",
            "url": "https://remote.deepflux.space/download/x.exe",
            "sha256_hex": "b".repeat(64),
            "size_bytes": 123
        });
        let m: UpdateManifest = serde_json::from_value(minimal).unwrap();
        assert_eq!(m.notes, "");
        assert_eq!(m.published_at, "");
    }

    #[test]
    fn human_size_formatting() {
        assert_eq!(human_size(7_340_032), "7.0 MB");
        assert_eq!(human_size(512 * 1024), "512 kB");
    }

    #[test]
    fn install_command_quoting() {
        let script = match build_install_command(
            Path::new(
                "C:\\Users\\igor k\\AppData\\Roaming\\space.deepflux.remote.desktop\\updates\\update-0.9.0-setup.exe",
            ),
            Path::new("C:\\Users\\igor k\\AppData\\Local\\Remote Desktop\\Remote Desktop.exe"),
        ) {
            InstallCommand::InstallAndRelaunch(script) => script,
            other => panic!("plain paths must get the relaunch wrapper: {other:?}"),
        };
        assert!(script.contains("start /wait \"\" \"C:\\Users\\igor k\\AppData\\Roaming\\space.deepflux.remote.desktop\\updates\\update-0.9.0-setup.exe\" /S"));
        assert!(script.contains(
            "start \"\" \"C:\\Users\\igor k\\AppData\\Local\\Remote Desktop\\Remote Desktop.exe\""
        ));
        assert!(script.starts_with("ping -n 3"));
        // Unsafe APP path: install-only wrapper (grace kept, no relaunch).
        match build_install_command(
            Path::new("C:\\ok\\x.exe"),
            Path::new("C:\\bad^path\\app.exe"),
        ) {
            InstallCommand::InstallOnly(script) => {
                assert!(script.contains("/S"));
                assert!(script.starts_with("ping -n 3"));
                assert!(!script.contains("app.exe"));
            }
            other => panic!("unsafe app path must drop the relaunch: {other:?}"),
        }
        // Unsafe INSTALLER path: bare spawn (no script at all).
        assert!(matches!(
            build_install_command(
                Path::new("C:\\bad&path\\x.exe"),
                Path::new("C:\\ok\\app.exe")
            ),
            InstallCommand::Bare
        ));
        assert!(path_safe_for_cmd("C:\\plain path\\app.exe"));
        assert!(!path_safe_for_cmd("C:\\a&b\\app.exe"));
    }

    #[test]
    fn verify_staged_three_branches() {
        let dir = std::env::temp_dir().join(format!("df-upd-verify-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let payload = b"installer-bytes".to_vec();
        let path = dir.join("update-9.9.9-setup.exe");
        let mut manifest = manifest_fixture();
        manifest.size_bytes = payload.len() as u64;
        manifest.sha256_hex = hex_lower(&Sha256::digest(&payload));
        // Good file passes.
        std::fs::write(&path, &payload).unwrap();
        assert!(verify_staged(&path, &manifest).is_ok());
        // Wrong size (truncated download) fails with plain copy.
        std::fs::write(&path, &payload[..5]).unwrap();
        let err = verify_staged(&path, &manifest).unwrap_err();
        assert!(err.contains("incomplete"), "copy: {err}");
        // Right size, wrong bytes — the core trust gate.
        std::fs::write(&path, vec![0u8; payload.len()]).unwrap();
        let err = verify_staged(&path, &manifest).unwrap_err();
        assert!(err.contains("didn't match"), "copy: {err}");
        // Missing file.
        std::fs::remove_file(&path).unwrap();
        assert!(verify_staged(&path, &manifest).is_err());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn purge_keeps_only_the_current_target() {
        let dir = std::env::temp_dir().join(format!("df-upd-test-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("update-0.9.0-setup.exe"), b"target").unwrap();
        std::fs::write(dir.join("update-0.9.0-setup.exe.dfresume"), b"{}").unwrap();
        std::fs::write(dir.join("update-0.8.0-setup.exe"), b"stale").unwrap();
        std::fs::write(dir.join("update-0.8.0-setup.exe.dfresume"), b"{}").unwrap();
        std::fs::write(dir.join("notes.txt"), b"unrelated").unwrap();
        purge_stale(&dir, "update-0.9.0-setup.exe");
        assert!(dir.join("update-0.9.0-setup.exe").exists());
        assert!(dir.join("update-0.9.0-setup.exe.dfresume").exists());
        assert!(!dir.join("update-0.8.0-setup.exe").exists());
        assert!(!dir.join("update-0.8.0-setup.exe.dfresume").exists());
        assert!(dir.join("notes.txt").exists());
        // A target WITHOUT resume state re-downloads from scratch.
        std::fs::remove_file(dir.join("update-0.9.0-setup.exe.dfresume")).unwrap();
        purge_stale(&dir, "update-0.9.0-setup.exe");
        assert!(!dir.join("update-0.9.0-setup.exe").exists());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn sha256_file_matches_known_digest() {
        let dir = std::env::temp_dir().join(format!("df-upd-sha-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("payload.bin");
        std::fs::write(&path, b"abc").unwrap();
        // SHA-256("abc") — well-known vector.
        assert_eq!(
            sha256_file(&path).unwrap(),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Minimal loopback HTTP server serving one JSON body.
    struct ManifestServer {
        url: String,
        shutdown: std::sync::Arc<AtomicBool>,
        handle: Option<std::thread::JoinHandle<()>>,
    }

    impl ManifestServer {
        fn start(body: String) -> Self {
            use std::io::{BufRead, BufReader, Write};
            let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
            let port = listener.local_addr().unwrap().port();
            let shutdown = std::sync::Arc::new(AtomicBool::new(false));
            let flag = std::sync::Arc::clone(&shutdown);
            let handle = std::thread::spawn(move || {
                listener.set_nonblocking(true).ok();
                loop {
                    if flag.load(Ordering::Relaxed) {
                        break;
                    }
                    match listener.accept() {
                        Ok((mut stream, _)) => {
                            let body = body.clone();
                            std::thread::spawn(move || {
                                let peer = stream.try_clone().unwrap();
                                let mut reader = BufReader::new(peer);
                                let mut line = String::new();
                                if reader.read_line(&mut line).is_err() {
                                    return;
                                }
                                loop {
                                    let mut h = String::new();
                                    match reader.read_line(&mut h) {
                                        Ok(0) | Err(_) => break,
                                        Ok(_) if h.trim().is_empty() => break,
                                        Ok(_) => {}
                                    }
                                }
                                let resp = format!(
                                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                                    body.len()
                                );
                                let _ = stream.write_all(resp.as_bytes());
                                let _ = stream.write_all(body.as_bytes());
                                let _ = stream.flush();
                            });
                        }
                        Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                            std::thread::sleep(Duration::from_millis(15));
                        }
                        Err(_) => break,
                    }
                }
            });
            Self {
                url: format!("http://127.0.0.1:{port}/latest.json"),
                shutdown,
                handle: Some(handle),
            }
        }
    }

    impl Drop for ManifestServer {
        fn drop(&mut self) {
            self.shutdown.store(true, Ordering::Relaxed);
            if let Some(h) = self.handle.take() {
                let _ = h.join();
            }
        }
    }

    #[test]
    fn http_manifest_is_refused_enforcing_https() {
        // The product rule: only HTTPS manifests are ever consumed. A
        // loopback (http) server — even serving a perfectly valid body —
        // must be refused by fetch_manifest's scheme gate.
        let server = ManifestServer::start(serde_json::to_string(&manifest_fixture()).unwrap());
        assert!(fetch_manifest(&server.url).is_err());
    }
}
